python3 -I - <<'PY'
import re,yaml,sys
m=yaml.safe_load(open('.claude/data/guard-origins.yaml'))
rows={g['id']:g for g in m['guards']}
tbl={}
for l in open('.claude/loa/reference/hooks-reference.md'):
    if not l.startswith('| ') or l.startswith('| Event'): continue
    c=[x.strip() for x in l.strip().strip('|').split(' | ')]
    if len(c)<6: continue
    ev,mt,script=c[0],c[1].replace('\\|','|'),c[2].strip('`')
    reg = ev if mt=='(all)' else f"{ev}:{mt}"
    wrapped = script.startswith('hook-guard.sh ')
    s = script.replace('hook-guard.sh ','')
    tbl.setdefault('hook:'+s,set()).add(reg)
    if wrapped: tbl.setdefault('hook:hook-guard.sh',set()).add(reg)
    r=rows.get('hook:'+s)
    if r is None: print("NO ROW", s); continue
    if r['status']!=c[3] or r['knob']!=c[4] or r['note']!=c[5]: print("MISMATCH", s, c[3:6], r['status'], r['knob'], r['note'])
for id,regs in tbl.items():
    r=rows.get(id)
    if sorted(r.get('registrations',[]))!=sorted(regs): print("REG MISMATCH", id, r.get('registrations'), sorted(regs))
hooks_in_map={k for k in rows if k.startswith('hook:')}
print("map hooks not in table:", hooks_in_map-set(tbl))
print("ok", len(tbl))
